287:   // Listen / poll for incoming repair requests when online & available
288:   useEffect(() => {
289:     if ((activeJob && activeJob.status !== 'completed' && activeJob.status !== 'cancelled') || incomingRequest) return;
290: 
291:     let isMounted = true;
292: 
293:     const checkIncoming = async () => {
294:       try {
295:         const { data: requests, error } = await supabase
296:           .from('repair_requests')
297:           .select(`
298:             id,
299:             customer_id,
300:             category_id,
301:             description,
302:             voice_note_url,
303:             latitude,
304:             longitude,
305:             address_text,
306:             status,
307:             created_at,
308:             tractors ( make, model, year, registration_number ),
309:             problem_categories ( id, name_en ),
310:             customers (
311:               id,
312:               profile:profiles ( full_name, phone, avatar_url )
313:             )
314:           `)
315:           .in('status', ['requested', 'matching'])
316:           .order('created_at', { ascending: false })
317:           .limit(1);
318: 
319:         if (error || !requests || requests.length === 0 || !isMounted) return;
320: 
321:         const req = requests[0];
322: 
323:         // Calculate approximate distance
324:         let distKm = 2.0;
325:         if (req.latitude && req.longitude) {
326:           const mechLat = 16.9885;
327:           const mechLon = 79.9689;
328:           const dLat = ((Number(req.latitude) - mechLat) * Math.PI) / 180;
329:           const dLon = ((Number(req.longitude) - mechLon) * Math.PI) / 180;
330:           const a =
331:             Math.sin(dLat / 2) * Math.sin(dLat / 2) +
332:             Math.cos((mechLat * Math.PI) / 180) *
333:               Math.cos((Number(req.latitude) * Math.PI) / 180) *
334:               Math.sin(dLon / 2) *
335:               Math.sin(dLon / 2);
336:           const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
337:           distKm = Math.round(6371 * c * 10) / 10;
338:         }
339: 
340:         // Fetch attached photos if available
341:         const { data: media } = await supabase
342:           .from('request_media')
343:           .select('file_path, media_type')
344:           .eq('request_id', req.id);
345: 
346:         const photoUrls = (media || [])
347:           .filter((m: any) => m.media_type === 'photo')
348:           .map((m: any) => supabase.storage.from('request-media').getPublicUrl(m.file_path).data.publicUrl);
349: 
350:         const cust = req.customers as any;
351:         const profileData = cust?.profile;
352:         const tractor = req.tractors as any;
353:         const category = req.problem_categories as any;
354: 
355:         const incoming = {
356:           id: req.id,
357:           requestId: req.id,
358:           distanceKm: distKm,
359:           etaMinutes: Math.max(5, Math.round(distKm * 2.5)),
360:           customerName: profileData?.full_name || 'Farmer (Customer)',
361:           customerPhone: profileData?.phone || '',
362:           customerArea: req.address_text || 'Nearby Village',
363:           village: '',
364:           mandal: '',
365:           district: '',
366:           latitude: Number(req.latitude || 0),
367:           longitude: Number(req.longitude || 0),
368:           tractorMake: tractor?.make || 'Tractor',
369:           tractorModel: tractor?.model || '',
370:           tractorYear: tractor?.year ? Number(tractor.year) : undefined,
371:           problemCategoryId: req.category_id,
372:           problemCategoryName: category?.name_en || 'Tractor Repair',
373:           reportedProblem: req.description || 'Tractor inspection & repair required',
374:           photoUrls,
375:           voiceNoteUrl: req.voice_note_url || null,
376:           expiresAt: new Date(Date.now() + 30000).toISOString(),
377:           secondsRemaining: 30,
378:         };
379: 
380:         if (isMounted) {
381:           useJobStore.getState().setIncomingRequest(incoming);
382:         }
383:       } catch (err) {
384:         console.warn('Error checking incoming requests:', err);
385:       }
386:     };
387: 
388:     // Check immediately
389:     checkIncoming();
390: 
391:     // Poll every 3 seconds while online & idle
392:     const interval = setInterval(checkIncoming, 3000);
393: 
394:     // Listen to real-time changes
395:     const channel = supabase
396:       .channel('mechanic-incoming-requests')
397:       .on(
398:         'postgres_changes',
399:         { event: '*', schema: 'public', table: 'repair_requests' },
400:         () => {
401:           checkIncoming();
402:         }
403:       )
404:       .subscribe();
405: 
406:     return () => {
407:       isMounted = false;
408:       clearInterval(interval);
409:       supabase.removeChannel(channel);
410:     };
