10: }
11: 
12: interface MechanicCandidate {
13:   mechanic_id: string;
14:   profile_id: string;
15:   full_name: string;
16:   phone: string | null;
17:   avatar_url: string | null;
18:   rating_avg: number;
19:   total_jobs: number;
20:   workshop_address: string | null;
21:   service_radius_km: number;
22:   distance_km: number;
