25: function haversineDistanceKm(lat1: number, lon1: number, lat2: number, lon2: number): number {
26:   const R = 6371; // Earth radius in km
27:   const dLat = ((lat2 - lat1) * Math.PI) / 180;
28:   const dLon = ((lon2 - lon1) * Math.PI) / 180;
29:   const a =
30:     Math.sin(dLat / 2) * Math.sin(dLat / 2) +
31:     Math.cos((lat1 * Math.PI) / 180) *
32:       Math.cos((lat2 * Math.PI) / 180) *
33:       Math.sin(dLon / 2) *
34:       Math.sin(dLon / 2);
35:   const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
36:   return Math.round(R * c * 100) / 100;
37: }
