1: // Supabase Edge Function: verify-code
2: // Validates start or finish codes entered by the mechanic.
3: // Rate limits attempts (max 3), enforces expiry, and transitions job status.
4: 
5: import { corsHeaders, jsonResponse, errorResponse } from '../_shared/cors.ts';
6: import { verifyCodeHash } from '../_shared/crypto.ts';
7: import { getSupabaseAdminClient, getUserFromRequest } from '../_shared/supabaseClient.ts';
8: 
9: interface VerifyCodePayload {
10:   jobId?: string;
11:   job_id?: string;
12:   code?: string;
13:   codeType?: 'start' | 'finish';
14:   code_type?: 'start' | 'finish';
15: }
16: 
17: Deno.serve(async (req: Request) => {
18:   if (req.method === 'OPTIONS') {
19:     return new Response('ok', { headers: corsHeaders });
20:   }
21: 
22:   if (req.method !== 'POST') {
23:     return errorResponse('Method not allowed', 405);
24:   }
25: 
26:   try {
27:     const supabase = getSupabaseAdminClient();
28:     const body: VerifyCodePayload = await req.json().catch(() => ({}));
29:     const jobId = body.jobId || body.job_id;
30:     const rawCode = body.code?.toString().trim();
31:     const codeType = body.codeType || body.code_type || 'start';
32: 
33:     if (!jobId) {
34:       return errorResponse('jobId is required', 400);
35:     }
36:     if (!rawCode) {
37:       return errorResponse('code is required', 400);
38:     }
39: 
40:     // 1. Get authenticated user context (if provided)
41:     const { user } = await getUserFromRequest(req);
42: 
43:     // 2. Fetch Job details
44:     const { data: job, error: jobErr } = await supabase
45:       .from('jobs')
46:       .select(`
47:         id,
48:         status,
49:         customer_id,
50:         mechanic_id,
51:         customers (
52:           profile_id
53:         ),
54:         mechanics (
55:           profile_id
56:         )
57:       `)
58:       .eq('id', jobId)
59:       .single();
60: 
61:     if (jobErr || !job) {
62:       return errorResponse('Job not found', 404);
63:     }
64: 
65:     // 3. Find the active secure code
66:     const { data: codeRecord, error: codeErr } = await supabase
67:       .from('secure_codes')
68:       .select('*')
69:       .eq('job_id', jobId)
70:       .eq('code_type', codeType)
71:       .eq('is_used', false)
72:       .order('created_at', { ascending: false })
73:       .limit(1)
74:       .maybeSingle();
75: 
76:     if (codeErr || !codeRecord) {
77:       return errorResponse(
78:         `No active ${codeType} code found for this job.`,
79:         404
80:       );
81:     }
82: 
83:     // 4. Check if max attempts (3) exceeded
84:     if (codeRecord.attempts >= codeRecord.max_attempts) {
85:       return errorResponse(
86:         `Maximum verification attempts (${codeRecord.max_attempts}) exceeded. Code is locked.`,
87:         429
88:       );
89:     }
90: 
91:     // 5. Check if expired
92:     const now = new Date();
93:     const expiresAt = new Date(codeRecord.expires_at);
94:     if (now > expiresAt) {
95:       return errorResponse(
96:         `This ${codeType} code has expired. Please request a new code.`,
97:         400
98:       );
99:     }
100: 
101:     // 6. Verify Code Hash
102:     let isValid = false;
103:     if (codeRecord.code && codeRecord.code.trim() === rawCode) {
104:       isValid = true;
105:     } else if (codeRecord.code_hash) {
106:       isValid = await verifyCodeHash(rawCode, codeRecord.code_hash);
107:     }
108: 
109:     if (!isValid) {
110:       const newAttempts = codeRecord.attempts + 1;
111:       await supabase
112:         .from('secure_codes')
113:         .update({ attempts: newAttempts })
114:         .eq('id', codeRecord.id);
115: 
116:       const attemptsRemaining = Math.max(0, codeRecord.max_attempts - newAttempts);
117: 
118:       await supabase.from('audit_logs').insert({
119:         user_id: user?.id || null,
120:         action: 'code_verification_failed',
121:         resource_type: 'secure_codes',
122:         resource_id: codeRecord.id,
123:         new_values: {
124:           jobId,
125:           codeType,
126:           attempts: newAttempts,
127:           attemptsRemaining,
128:         },
129:       });
130: 
131:       return errorResponse(
132:         `Invalid ${codeType} code. ${attemptsRemaining} attempt(s) remaining.`,
133:         400,
134:         { attemptsRemaining }
135:       );
136:     }
137: 
138:     // 7. Mark Code as Used
139:     await supabase
140:       .from('secure_codes')
141:       .update({
142:         is_used: true,
143:         used_at: now.toISOString(),
144:         verified_by: user?.id || null,
145:       })
146:       .eq('id', codeRecord.id);
147: 
148:     const customerProfileId = (job as any).customers?.profile_id;
149:     const mechanicProfileId = (job as any).mechanics?.profile_id;
150: 
151:     let targetJobStatus = job.status;
152: 
153:     // 8. Handle 'start' code logic
154:     if (codeType === 'start') {
155:       targetJobStatus = 'repair_in_progress';
156: 
157:       await supabase
158:         .from('jobs')
159:         .update({
160:           status: 'repair_in_progress',
161:           repair_started_at: now.toISOString(),
162:           updated_at: now.toISOString(),
163:         })
164:         .eq('id', jobId);
165: 
166:       await supabase.from('job_status_history').insert({
167:         job_id: jobId,
168:         old_status: job.status,
169:         new_status: 'repair_in_progress',
170:         changed_by: user?.id || null,
171:         notes: 'Start code verified by mechanic. Work began.',
172:       });
173: 
174:       if (customerProfileId) {
175:         await supabase.from('notifications').insert({
176:           user_id: customerProfileId,
177:           type: 'job_update',
178:           title: 'Repair Started',
179:           body: 'The mechanic has verified your start code and began repairing your tractor.',
180:           data: { jobId, status: 'repair_in_progress' },
181:         });
182:       }
183: 
184:       await supabase.from('audit_logs').insert({
185:         user_id: user?.id || null,
186:         action: 'start_code_verified',
187:         resource_type: 'jobs',
188:         resource_id: jobId,
189:         new_values: { status: 'repair_in_progress' },
190:       });
191:     }
192: 
193:     // 9. Handle 'finish' code logic
194:     if (codeType === 'finish') {
195:       targetJobStatus = 'completed';
196: 
197:       await supabase
198:         .from('jobs')
199:         .update({
200:           status: 'completed',
201:           completed_at: now.toISOString(),
202:           repair_completed_at: now.toISOString(),
203:           updated_at: now.toISOString(),
204:         })
205:         .eq('id', jobId);
206: 
207:       // If an invoice exists in pending status (e.g. cash payment), mark it paid
208:       const { data: invoice } = await supabase
209:         .from('invoices')
210:         .select('id, status')
211:         .eq('job_id', jobId)
212:         .maybeSingle();
213: 
214:       if (invoice && invoice.status === 'pending') {
215:         await supabase
216:           .from('invoices')
217:           .update({
218:             status: 'paid',
219:             updated_at: now.toISOString(),
220:           })
221:           .eq('id', invoice.id);
222:       }
223: 
224:       await supabase.from('job_status_history').insert({
225:         job_id: jobId,
226:         old_status: job.status,
227:         new_status: 'completed',
228:         changed_by: user?.id || null,
229:         notes: 'Finish code verified. Repair completed successfully.',
230:       });
231: 
232:       if (customerProfileId) {
233:         await supabase.from('notifications').insert({
234:           user_id: customerProfileId,
235:           type: 'job_update',
236:           title: 'Job Completed!',
237:           body: 'Your tractor repair has been marked complete. Please rate your mechanic.',
238:           data: { jobId, status: 'completed' },
239:         });
240:       }
241: 
242:       await supabase.from('audit_logs').insert({
243:         user_id: user?.id || null,
244:         action: 'finish_code_verified',
245:         resource_type: 'jobs',
246:         resource_id: jobId,
247:         new_values: { status: 'completed' },
248:       });
249:     }
250: 
251:     return jsonResponse({
252:       success: true,
253:       message: `${codeType === 'start' ? 'Start' : 'Finish'} code verified successfully.`,
254:       jobId,
255:       codeType,
256:       jobStatus: targetJobStatus,
257:     });
258:   } catch (err: any) {
259:     console.error('Unhandled error in verify-code:', err);
260:     return errorResponse(err.message || 'Internal server error', 500);
261:   }
262: });

