'use server';

import { createAdminClient } from '../supabase/admin';
import { revalidatePath } from 'next/cache';

export async function getAppSettings() {
  const adminClient = createAdminClient();

  const { data, error } = await adminClient
    .from('app_settings')
    .select('*')
    .order('key');

  if (error) {
    console.error('Error fetching app settings:', error);
    return [];
  }

  return data || [];
}

export async function updateAppSetting(
  key: string,
  value: string,
  adminUserId?: string
) {
  const adminClient = createAdminClient();

  const { data: oldSetting } = await adminClient
    .from('app_settings')
    .select('value')
    .eq('key', key)
    .single();

  const { error } = await adminClient
    .from('app_settings')
    .update({
      value,
      updated_at: new Date().toISOString(),
      updated_by: adminUserId || null,
    })
    .eq('key', key);

  if (error) {
    return { success: false, error: error.message };
  }

  // Audit log
  try {
    await adminClient.from('audit_logs').insert({
      user_id: adminUserId || null,
      action: 'update_app_setting',
      entity_type: 'app_setting',
      entity_id: key,
      old_values: { value: oldSetting?.value },
      new_values: { value },
    });
  } catch (err) {
    console.error('Audit log failed:', err);
  }

  revalidatePath('/settings');
  return { success: true };
}

export async function getProblemCategories() {
  const adminClient = createAdminClient();

  const { data, error } = await adminClient
    .from('problem_categories')
    .select('*')
    .order('sort_order', { ascending: true });

  if (error) {
    console.error('Error fetching categories:', error);
    return [];
  }

  return data || [];
}

export async function upsertProblemCategory(
  category: {
    id?: string;
    name_en: string;
    name_te: string;
    name_hi: string;
    icon?: string;
    sort_order?: number;
    base_price_estimate?: number;
    is_active?: boolean;
  },
  adminUserId?: string
) {
  const adminClient = createAdminClient();

  if (category.id) {
    const { error } = await adminClient
      .from('problem_categories')
      .update({
        name_en: category.name_en,
        name_te: category.name_te,
        name_hi: category.name_hi,
        icon: category.icon || 'wrench',
        sort_order: category.sort_order || 0,
        base_price_estimate: category.base_price_estimate || 0,
        is_active: category.is_active ?? true,
      })
      .eq('id', category.id);

    if (error) return { success: false, error: error.message };
  } else {
    const { error } = await adminClient
      .from('problem_categories')
      .insert({
        name_en: category.name_en,
        name_te: category.name_te,
        name_hi: category.name_hi,
        icon: category.icon || 'wrench',
        sort_order: category.sort_order || 0,
        base_price_estimate: category.base_price_estimate || 0,
        is_active: category.is_active ?? true,
      });

    if (error) return { success: false, error: error.message };
  }

  // Audit log
  try {
    await adminClient.from('audit_logs').insert({
      user_id: adminUserId || null,
      action: category.id ? 'update_problem_category' : 'create_problem_category',
      entity_type: 'problem_category',
      entity_id: category.id || category.name_en,
      new_values: category,
    });
  } catch (err) {
    console.error('Audit log failed:', err);
  }

  revalidatePath('/settings');
  return { success: true };
}

export async function toggleProblemCategory(
  id: string,
  isActive: boolean,
  adminUserId?: string
) {
  const adminClient = createAdminClient();

  const { error } = await adminClient
    .from('problem_categories')
    .update({ is_active: isActive, updated_at: new Date().toISOString() })
    .eq('id', id);

  if (error) return { success: false, error: error.message };

  revalidatePath('/settings');
  return { success: true };
}

