export async function getCancellationMetrics() {
  const adminClient = createAdminClient();

  const { data: customers } = await adminClient
    .from('customers')
    .select(
      `
      id,
      cancellation_count,
      profile:profiles (
        id,
        full_name,
        phone,
        is_active
      )
    `
    )
    .order('cancellation_count', { ascending: false })
