export async function getJobs(options?: {
  status?: string;
  search?: string;
  problemArea?: string;
  mechanicId?: string;
  date?: string;
  page?: number;
  limit?: number;
}) {
  const adminClient = createAdminClient();
  const page = options?.page || 1;
  const limit = options?.limit || 25;
  const from = (page - 1) * limit;
  const to = from + limit - 1;

  let query = adminClient
    .from('jobs')
    .select(
      `
      *,
      customer:customers (
        id,
        profile:profiles (
          id,
          full_name,
          phone,
          avatar_url
        )
      ),
      mechanic:mechanics (
        id,
